//
//  BoundedZipArchiveTests
//  reynard-browser-zh: limits for untrusted ZIP files read through ZIPFoundation.
//  Fixtures are generated by make_fixtures.py.
//

import Foundation
import ZIPFoundation

let dir = URL(fileURLWithPath: CommandLine.arguments[1])
var failures = 0
func check(_ name: String, _ ok: Bool) { print(ok ? "PASS" : "FAIL", name); if !ok { failures += 1 } }
let small = BoundedZipArchive.Limits(maximumArchiveSize: 1 << 20, maximumEntryCount: 8, maximumEntrySize: 4096, maximumTotalSize: 6000)

func read(_ file: String, _ path: String, _ limits: BoundedZipArchive.Limits = small) -> Result<Data, Error> {
    Result {
        let a = try BoundedZipArchive.open(dir.appendingPathComponent(file), limits: limits)
        guard let e = try BoundedZipArchive.fileEntry(at: path, in: a, limits: limits) else { throw NSError(domain: "notfound", code: 0) }
        return try BoundedZipArchive.data(of: e, from: a, limits: limits)
    }
}
func isFailure(_ r: Result<Data, Error>, _ match: (Error) -> Bool) -> Bool { if case .failure(let e) = r { return match(e) }; return false }

check("ok stored+deflate", (try? read("ok.zip", "icons/a.png").get()) == Data(repeating: 65, count: 3000) && (try? read("ok.zip", "b.txt").get()) == Data("hello".utf8))
check("bomb (declared small, inflates more) rejected", isFailure(read("bomb.zip", "x.bin", BoundedZipArchive.Limits(maximumArchiveSize: 1 << 20, maximumEntryCount: 8, maximumEntrySize: 1 << 30, maximumTotalSize: 1 << 30))) { if case BoundedZipArchive.Failure.invalidEntry = $0 { return true }; return false })
check("entry too large rejected", isFailure(read("big.zip", "big.bin")) { if case BoundedZipArchive.Failure.limitExceeded = $0 { return true }; return false })
check("too many entries rejected", isFailure(read("many.zip", "f0")) { if case BoundedZipArchive.Failure.limitExceeded = $0 { return true }; return false })
check("unsafe path not returned", (try? read("ok.zip", "../b.txt").get()) == nil)
check("crc mismatch rejected", isFailure(read("crc.zip", "b.txt")) { if case BoundedZipArchive.Failure.invalidEntry = $0 { return true }; return false })
check("archive size limit", isFailure(read("ok.zip", "b.txt", BoundedZipArchive.Limits(maximumArchiveSize: 10, maximumEntryCount: 8, maximumEntrySize: 4096, maximumTotalSize: 4096))) { if case BoundedZipArchive.Failure.limitExceeded = $0 { return true }; return false })
check("not a zip", isFailure(read("notzip.zip", "b.txt")) { if case BoundedZipArchive.Failure.invalidArchive = $0 { return true }; return false })
// total budget across entries
do {
    let a = try BoundedZipArchive.open(dir.appendingPathComponent("ok.zip"), limits: small)
    var total: UInt64 = 0
    let entries = try BoundedZipArchive.entries(of: a, limits: small)
    var hitLimit = false
    for _ in 0..<3 { for e in entries where e.type == .file && BoundedZipArchive.isSafeEntryPath(e.path) {
        do { try BoundedZipArchive.extract(e, from: a, limits: small, totalSize: &total) { _ in } } catch BoundedZipArchive.Failure.limitExceeded { hitLimit = true }
    } }
    check("total budget enforced (total=\(total))", hitLimit && total <= 6000)
} catch { check("total budget: \(error)", false) }
// cancellation
do {
    let a = try BoundedZipArchive.open(dir.appendingPathComponent("ok.zip"), limits: small)
    let e = try BoundedZipArchive.fileEntry(at: "icons/a.png", in: a, limits: small)!
    var total: UInt64 = 0
    var cancelled = false
    do { try BoundedZipArchive.extract(e, from: a, limits: small, totalSize: &total, checkCancellation: { throw CancellationError() }) { _ in } } catch is CancellationError { cancelled = true }
    check("cancellation propagates", cancelled && total == 0)
} catch { check("cancel: \(error)", false) }
// backslash / absolute path helpers
check("path checks", !BoundedZipArchive.isSafeEntryPath("/etc/x") && !BoundedZipArchive.isSafeEntryPath("a\\b") && !BoundedZipArchive.isSafeEntryPath("a/../b") && !BoundedZipArchive.isSafeEntryPath("") && BoundedZipArchive.isSafeEntryPath("icons/a.png"))
if failures == 0 { print("BoundedZipArchiveTests: all tests passed") }
exit(failures == 0 ? 0 : 1)
